runtime=R/'ada_run/ca-elementary-review-2026-09-13'
if (runtime/'run.json').exists():
 run=json.loads((runtime/'run.json').read_text())
 valid=run.get('exit')==0 and run.get('sources_unchanged') and all((R/p).exists() and hashlib.sha256((R/p).read_bytes()).hexdigest()==h for p,h in run['source_sha256'].items())
 if valid:
  shots=[]
  for name,caption in [('entrance','From the entrance at 1.6 m eye height. The console now stands beside the volume.'),('controls','The real readout and five controls, after one generation. All five passed desktop pointer checks.'),('study','The same structure from the side: occupied and fading cells above the original opening.')]:
   rel='ca-elementary-'+name+'.png';shutil.copy2(runtime/'CA_ElementaryRules'/f'{name}.png',O/rel);manifest.append('possible-bodies/'+rel)
   shots.append(f'<figure style="margin:24px 0"><a href="{rel}"><img src="{rel}" alt="{caption}" style="width:100%;border-radius:10px"></a><figcaption>{caption}</figcaption></figure>')
  gallery='<section id="in-museum"><div class="eyebrow">Actual Godot captures</div><h2>Inside the endless museum</h2><p>The current room, captured on 13 September. The first capture exposed a readout that obscured the work; its case is now narrower, its lettering larger, and its position shifted to the side. These views use the actual museum scene and retained structure-growth artifact.</p>'+''.join(shots)+'<p class="small">21 desktop checks passed. The original editor stayed open; the capture used an isolated copy of the museum layout and saved hand. One full-volume update took 144 ms in the latest run; frame cost needs optimisation before headset acceptance. Physical route traversal and headset checks remain pending.</p></section>'
  page=page.replace('<div class="lab">',gallery+'<div class="lab">',1)
  page=page.replace('Godot walkthrough, pointer reach and performance checks are pending. This page is an independent web experiment, not a game recording.','Actual Godot captures and 21 desktop checks are now available below. Headset and route traversal checks remain pending. The interactive web experiment is a separate smaller model.')
  page=page.replace('The volume moves away from the spawn and is scaled to fit above the opening; a console stands on its entry rim.','The volume moves away from the spawn and is scaled to fit above the opening; a console stands to one side of its entry rim.')
save('ca-elementary-rules.html',page.replace('__FINAL__',md('final.md')).replace('__CRITICAL__',md('critical.md')).replace('__TECHNICAL__',md('technical.md')))
save('ca-elementary-model.js',(R/'tools/ca_elementary_model.js').read_text())
verification=REC/'verification.json'
evidence=json.loads(verification.read_text()) if verification.exists() else {'status':'checks in progress','godot_verified':False,'headset_verified':False}
browser_record=REC/'browser-verification.json'
if browser_record.exists():evidence['browser']=json.loads(browser_record.read_text())
