(REC/'publish-targets.json').write_bytes((json.dumps(manifest,indent=2)+'\n').encode())
(REC/'publish-hashes.json').write_bytes((json.dumps({p:hashlib.sha256((R/'doc/research'/p).read_bytes()).hexdigest() for p in manifest},indent=2)+'\n').encode())
print('Built',len(manifest),'review files.')
